            row_groups.append((start, r))
        start = r + 1

    col_groups = []
    start = 0
    for c in sep_cols + [w]:
        if start < c:
            col_groups.append((start, c))
        start = c + 1

    tiles = []
    for r0, r1 in row_groups:
        for c0, c1 in col_groups:
            tiles.append(tuple(tuple(grid[r][c0:c1]) for r in range(r0, r1)))

    counts = Counter(tiles)
    common = counts.most_common(1)[0][0]
    odd = next(tile for tile in tiles if tile != common)
    return [
        [1 if odd[r][c] != common[r][c] else common[r][c]
         for c in range(len(common[0]))]
        for r in range(len(common))
    ]
